-- Ally Grundstand (Bauschritt 3, D.3), erzeugt von werkzeuge/d3_grundstand.py aus SYS-2-Lesung (Ausführungen in lesung.json).
-- Reihenfolge: schema_vor.sql, startwerte.sql, schema_nach.sql.
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET search_path = public;
SELECT setval(pg_get_serial_sequence('public.mail_kategorien', 'id'), coalesce((SELECT max(id) FROM public.mail_kategorien), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('public.talents_briefings', 'id'), coalesce((SELECT max(id) FROM public.talents_briefings), 0) + 1, false);
